"""Rewrite the privacy policy in all 43 markets.

The old text said "CoreSkillAI collects no personal data ... No results are
transmitted to any server" and "No cross-site tracking". The second was already
untrue - AdSense is cross-site tracking by design - and the first is about to
become untrue the moment the response database is bound.

A policy that describes collection AFTER it starts is worthless. This lands
first; the database is bound second.

It also states plainly the thing most policies dodge: because the data holds no
identifier, we CANNOT find or delete one person's record on request. Pretending
otherwise would be a promise we could not keep.
"""
import os, sys, io, re
sys.path.insert(0, os.path.join(os.getcwd(), '_build'))
import tools as T

MAIL = '<a href="mailto:ocultmaster9@gmail.com">ocultmaster9@gmail.com</a>'
GOOG = '<a href="https://policies.google.com/privacy" target="_blank" rel="noopener">%s</a>'

# lang -> (collect, why, storage, ads, analytics, rights, contact) labels+text
K = {
"en": ["What we collect","When you finish the IQ or Pattern test we record how it went: which puzzle rules appeared, whether each was answered correctly, how long each took, your total score, your language and the date. We do not record your name, email, IP address, or any account or device identifier, and we set nothing that would let us recognise you if you came back.","Why","This test has no standardisation sample yet. Response data is the only way to measure how hard each puzzle actually is and how well it separates strong reasoning from weak, which is what turns a plausible-looking score into a meaningful one. It is not used for anything else and is never sold.","Cookies and local storage","We keep your theme and language choice in your browser's local storage. We write nothing else to your device.","Advertising","We use Google AdSense. Google may set cookies and use them to show relevant ads. See Google's %s.","Analytics","We use Google Analytics to see which pages get visited. Google collects that on its own terms, which include approximate location and device type.","Your data","Because the test records contain nothing that identifies you, we cannot locate, export or delete an individual person's entry — there is no link back to you. If you would rather nothing were collected, simply do not finish the test: nothing is sent until your result appears.","Contact"],
"af": ["Wat ons versamel","Wanneer jy die IK- of Patroontoets voltooi, teken ons aan hoe dit verloop het: watter puzzelreëls verskyn het, of elkeen korrek beantwoord is, hoe lank elkeen geneem het, jou totaal, jou taal en die datum. Ons teken nie jou naam, e-pos, IP-adres of enige rekening- of toestelidentifiseerder aan nie, en ons stel niks wat ons jou sou laat herken as jy terugkom nie.","Waarom","Hierdie toets het nog geen standaardiseringsteekproef nie. Responsdata is die enigste manier om te meet hoe moeilik elke puzzel werklik is en hoe goed dit sterk van swak redenasie skei — dít maak van 'n aanneemlike telling 'n betekenisvolle een. Dit word vir niks anders gebruik nie en word nooit verkoop nie.","Koekies en plaaslike berging","Ons hou jou tema- en taalkeuse in jou blaaier se plaaslike berging. Ons skryf niks anders na jou toestel nie.","Advertensies","Ons gebruik Google AdSense. Google kan koekies stel en dit gebruik om relevante advertensies te wys. Sien Google se %s.","Analise","Ons gebruik Google Analytics om te sien watter bladsye besoek word. Google versamel dit op sy eie voorwaardes, wat geskatte ligging en toesteltipe insluit.","Jou data","Omdat die toetsrekords niks bevat wat jou identifiseer nie, kan ons nie 'n individuele persoon se inskrywing opspoor, uitvoer of skrap nie — daar is geen skakel terug na jou nie. Verkies jy dat niks versamel word nie, voltooi eenvoudig nie die toets nie: niks word gestuur voordat jou uitslag verskyn nie.","Kontak"],
"ar": ["ما الذي نجمعه","عند إنهائك اختبار الذكاء أو اختبار الأنماط نسجّل كيف سار: أي قواعد ألغاز ظهرت، وهل أُجيب عن كل منها بشكل صحيح، وكم استغرق كل لغز، ودرجتك الكلية، ولغتك، والتاريخ. لا نسجّل اسمك ولا بريدك ولا عنوان IP ولا أي معرّف حساب أو جهاز، ولا نضع شيئًا يتيح لنا التعرف عليك إن عدت.","لماذا","لا تملك هذه الأداة عينة تقنين بعد. بيانات الاستجابة هي السبيل الوحيد لقياس صعوبة كل لغز فعليًا ومدى تمييزه بين الاستدلال القوي والضعيف، وهو ما يحوّل درجة تبدو معقولة إلى درجة ذات معنى. لا تُستخدم لغير ذلك ولا تُباع أبدًا.","الكوكيز والتخزين المحلي","نحفظ اختيارك للسمة واللغة في التخزين المحلي لمتصفحك. ولا نكتب شيئًا آخر على جهازك.","الإعلانات","نستخدم Google AdSense. قد تضع Google ملفات تعريف ارتباط وتستخدمها لعرض إعلانات ملائمة. راجع %s الخاصة بـGoogle.","التحليلات","نستخدم Google Analytics لمعرفة الصفحات التي تُزار. تجمع Google ذلك وفق شروطها الخاصة، وتشمل الموقع التقريبي ونوع الجهاز.","بياناتك","لأن سجلات الاختبار لا تتضمن ما يعرّفك، لا يمكننا العثور على سجل شخص بعينه أو تصديره أو حذفه — لا يوجد رابط يعود إليك. وإن كنت تفضّل ألا يُجمع شيء، فلا تُكمل الاختبار ببساطة: لا يُرسل شيء قبل ظهور نتيجتك.","التواصل"],
"bg": ["Какво събираме","Когато завършите теста за интелигентност или за модели, записваме как е протекъл: кои правила на задачите се появиха, дали всяка е решена вярно, колко време отне всяка, общия ви резултат, езика и датата. Не записваме име, имейл, IP адрес, нито идентификатор на акаунт или устройство, и не поставяме нищо, което би ни позволило да ви разпознаем при следващо посещение.","Защо","Този тест още няма стандартизационна извадка. Данните от отговорите са единственият начин да измерим колко трудна е всяка задача в действителност и доколко разделя силното от слабото мислене — това превръща правдоподобния резултат в смислен. Не се използват за нищо друго и не се продават.","Бисквитки и локално хранилище","Пазим избора ви на тема и език в локалното хранилище на браузъра. Нищо друго не записваме на устройството ви.","Реклама","Използваме Google AdSense. Google може да поставя бисквитки и да ги използва за подходящи реклами. Вижте %s на Google.","Анализи","Използваме Google Analytics, за да виждаме кои страници се посещават. Google събира това по свои условия, включително приблизително местоположение и тип устройство.","Вашите данни","Тъй като записите от теста не съдържат нищо, което да ви идентифицира, не можем да намерим, изнесем или изтрием записа на конкретен човек — няма връзка обратно към вас. Ако предпочитате нищо да не се събира, просто не завършвайте теста: нищо не се изпраща преди да се появи резултатът.","Контакт"],
"cs": ["Co sbíráme","Když dokončíte test IQ nebo test vzorů, zaznamenáme, jak proběhl: která pravidla úloh se objevila, zda byla každá zodpovězena správně, jak dlouho každá trvala, váš celkový výsledek, jazyk a datum. Nezaznamenáváme jméno, e-mail, IP adresu ani žádný identifikátor účtu či zařízení a neukládáme nic, podle čeho bychom vás poznali při návratu.","Proč","Tento test zatím nemá standardizační vzorek. Data z odpovědí jsou jediný způsob, jak změřit, jak obtížná každá úloha skutečně je a jak dobře odlišuje silné uvažování od slabého — právě to promění věrohodně vypadající skóre ve smysluplné. K ničemu jinému se nepoužívají a nikdy se neprodávají.","Cookies a místní úložiště","Vaši volbu motivu a jazyka držíme v místním úložišti prohlížeče. Nic dalšího na vaše zařízení nezapisujeme.","Reklama","Používáme Google AdSense. Google může nastavovat cookies a používat je k zobrazení relevantních reklam. Viz %s společnosti Google.","Analytika","Používáme Google Analytics, abychom viděli, které stránky se navštěvují. Google to sbírá za vlastních podmínek, včetně přibližné polohy a typu zařízení.","Vaše údaje","Protože záznamy z testu neobsahují nic, co by vás identifikovalo, nedokážeme najít, exportovat ani smazat záznam konkrétní osoby — neexistuje vazba zpět na vás. Pokud si nepřejete, aby se cokoli sbíralo, jednoduše test nedokončete: nic se neodesílá, dokud se neobjeví výsledek.","Kontakt"],
"da": ["Hvad vi indsamler","Når du afslutter IQ- eller mønstertesten, registrerer vi, hvordan det gik: hvilke opgaveregler der optrådte, om hver blev besvaret rigtigt, hvor lang tid hver tog, din samlede score, dit sprog og datoen. Vi registrerer ikke navn, e-mail, IP-adresse eller nogen konto- eller enheds-id, og vi gemmer intet, der lader os genkende dig, hvis du kommer igen.","Hvorfor","Testen har endnu ingen standardiseringsstikprøve. Svardata er den eneste måde at måle, hvor svær hver opgave faktisk er, og hvor godt den adskiller stærk ræsonnering fra svag — det er dét, der gør en sandsynligt udseende score meningsfuld. Data bruges ikke til andet og sælges aldrig.","Cookies og lokal lagring","Vi gemmer dit valg af tema og sprog i browserens lokale lagring. Vi skriver intet andet til din enhed.","Annoncering","Vi bruger Google AdSense. Google kan sætte cookies og bruge dem til at vise relevante annoncer. Se Googles %s.","Analyse","Vi bruger Google Analytics til at se, hvilke sider der besøges. Google indsamler det på egne vilkår, herunder omtrentlig placering og enhedstype.","Dine data","Fordi testregistreringerne intet indeholder, der identificerer dig, kan vi ikke finde, eksportere eller slette en enkelt persons post — der er ingen forbindelse tilbage til dig. Foretrækker du, at intet indsamles, så lad være med at gennemføre testen: intet sendes, før dit resultat vises.","Kontakt"],
"de": ["Was wir erheben","Wenn Sie den IQ- oder Mustertest beenden, halten wir fest, wie er verlief: welche Aufgabenregeln auftraten, ob jede richtig beantwortet wurde, wie lange jede dauerte, Ihr Gesamtergebnis, Ihre Sprache und das Datum. Wir erfassen weder Namen, E-Mail, IP-Adresse noch eine Konto- oder Gerätekennung und speichern nichts, woran wir Sie bei einem erneuten Besuch erkennen könnten.","Warum","Dieser Test hat noch keine Normstichprobe. Antwortdaten sind der einzige Weg, um zu messen, wie schwer jede Aufgabe tatsächlich ist und wie gut sie starkes von schwachem Denken trennt — genau das macht aus einem plausibel wirkenden Wert einen aussagekräftigen. Sie werden für nichts anderes genutzt und nie verkauft.","Cookies und lokaler Speicher","Ihre Auswahl von Design und Sprache liegt im lokalen Speicher Ihres Browsers. Sonst schreiben wir nichts auf Ihr Gerät.","Werbung","Wir nutzen Google AdSense. Google kann Cookies setzen und damit passende Anzeigen ausspielen. Siehe Googles %s.","Analyse","Wir nutzen Google Analytics, um zu sehen, welche Seiten aufgerufen werden. Google erhebt das zu eigenen Bedingungen, einschließlich ungefährem Standort und Gerätetyp.","Ihre Daten","Da die Testdatensätze nichts enthalten, was Sie identifiziert, können wir den Eintrag einer einzelnen Person weder finden noch exportieren oder löschen — es gibt keine Verbindung zu Ihnen. Wenn Sie lieber gar nichts erhoben haben möchten, beenden Sie den Test einfach nicht: vor Erscheinen Ihres Ergebnisses wird nichts gesendet.","Kontakt"],
"el": ["Τι συλλέγουμε","Όταν ολοκληρώνετε το τεστ νοημοσύνης ή μοτίβων, καταγράφουμε πώς πήγε: ποιοι κανόνες ερωτημάτων εμφανίστηκαν, αν απαντήθηκε σωστά το καθένα, πόσο χρόνο πήρε το καθένα, τη συνολική σας βαθμολογία, τη γλώσσα και την ημερομηνία. Δεν καταγράφουμε όνομα, email, διεύθυνση IP ούτε αναγνωριστικό λογαριασμού ή συσκευής, και δεν αποθηκεύουμε τίποτα που θα μας επέτρεπε να σας αναγνωρίσουμε αν επιστρέψετε.","Γιατί","Το τεστ δεν έχει ακόμη δείγμα στάθμισης. Τα δεδομένα απαντήσεων είναι ο μόνος τρόπος να μετρηθεί πόσο δύσκολο είναι πραγματικά κάθε ερώτημα και πόσο καλά ξεχωρίζει την ισχυρή από την αδύναμη σκέψη — αυτό μετατρέπει μια εύλογη βαθμολογία σε ουσιαστική. Δεν χρησιμοποιούνται για τίποτε άλλο και δεν πωλούνται ποτέ.","Cookies και τοπική αποθήκευση","Κρατάμε την επιλογή θέματος και γλώσσας στην τοπική αποθήκευση του προγράμματος περιήγησης. Τίποτε άλλο δεν γράφουμε στη συσκευή σας.","Διαφήμιση","Χρησιμοποιούμε το Google AdSense. Η Google μπορεί να θέτει cookies και να τα χρησιμοποιεί για σχετικές διαφημίσεις. Δείτε την %s της Google.","Αναλυτικά","Χρησιμοποιούμε το Google Analytics για να βλέπουμε ποιες σελίδες επισκέπτονται. Η Google τα συλλέγει με δικούς της όρους, που περιλαμβάνουν κατά προσέγγιση τοποθεσία και τύπο συσκευής.","Τα δεδομένα σας","Επειδή οι εγγραφές του τεστ δεν περιέχουν τίποτα που να σας ταυτοποιεί, δεν μπορούμε να εντοπίσουμε, να εξαγάγουμε ή να διαγράψουμε την εγγραφή ενός συγκεκριμένου ατόμου — δεν υπάρχει σύνδεση πίσω σε εσάς. Αν προτιμάτε να μη συλλεχθεί τίποτα, απλώς μην ολοκληρώσετε το τεστ: τίποτα δεν αποστέλλεται πριν εμφανιστεί το αποτέλεσμά σας.","Επικοινωνία"],
"es": ["Qué recogemos","Cuando terminas el test de IQ o el de patrones registramos cómo fue: qué reglas de puzle aparecieron, si acertaste cada una, cuánto tardaste en cada una, tu puntuación total, tu idioma y la fecha. No registramos nombre, correo, dirección IP ni ningún identificador de cuenta o dispositivo, y no guardamos nada que nos permita reconocerte si vuelves.","Por qué","Este test aún no tiene muestra de estandarización. Los datos de respuesta son la única forma de medir cuán difícil es realmente cada puzle y cuánto separa el razonamiento fuerte del débil, que es lo que convierte una puntuación verosímil en una significativa. No se usan para nada más y nunca se venden.","Cookies y almacenamiento local","Guardamos tu elección de tema e idioma en el almacenamiento local del navegador. No escribimos nada más en tu dispositivo.","Publicidad","Usamos Google AdSense. Google puede poner cookies y usarlas para mostrar anuncios relevantes. Consulta la %s de Google.","Analítica","Usamos Google Analytics para ver qué páginas se visitan. Google lo recoge según sus propias condiciones, que incluyen ubicación aproximada y tipo de dispositivo.","Tus datos","Como los registros del test no contienen nada que te identifique, no podemos localizar, exportar ni borrar la entrada de una persona concreta: no hay vínculo de vuelta a ti. Si prefieres que no se recoja nada, simplemente no termines el test: no se envía nada hasta que aparece tu resultado.","Contacto"],
"et": ["Mida me kogume","Kui lõpetad IQ- või mustritesti, salvestame, kuidas läks: millised ülesandereeglid esinesid, kas igaüks sai õige vastuse, kui kaua igaüks võttis, sinu koondtulemuse, keele ja kuupäeva. Me ei salvesta nime, e-posti, IP-aadressi ega ühtki konto- või seadmetunnust ja me ei salvesta midagi, mille järgi sind tagasi tulles ära tunneksime.","Miks","Sellel testil pole veel standardiseerimisvalimit. Vastusandmed on ainus viis mõõta, kui raske iga ülesanne tegelikult on ja kui hästi see eristab tugevat arutlust nõrgast — just see muudab usutava tulemuse sisukaks. Neid ei kasutata millekski muuks ega müüda kunagi.","Küpsised ja kohalik salvestus","Hoiame sinu teema- ja keelevaliku brauseri kohalikus salvestuses. Muud me sinu seadmesse ei kirjuta.","Reklaam","Kasutame Google AdSense'i. Google võib seada küpsiseid ja kasutada neid asjakohaste reklaamide näitamiseks. Vaata Google'i %s.","Analüütika","Kasutame Google Analyticsit, et näha, milliseid lehti külastatakse. Google kogub seda oma tingimustel, sealhulgas ligikaudset asukohta ja seadme tüüpi.","Sinu andmed","Kuna testikirjed ei sisalda midagi, mis sind tuvastaks, ei saa me üksikisiku kirjet leida, eksportida ega kustutada — puudub seos sinuga. Kui eelistad, et midagi ei koguta, lihtsalt ära lõpeta testi: enne tulemuse ilmumist ei saadeta midagi.","Kontakt"],
"fa": ["چه چیزی جمع می‌کنیم","وقتی آزمون هوش یا آزمون الگو را تمام می‌کنید، ثبت می‌کنیم که چگونه پیش رفت: کدام قاعده‌های معما ظاهر شدند، آیا هرکدام درست پاسخ داده شد، هر کدام چقدر طول کشید، نمرهٔ کل، زبان و تاریخ. نام، ایمیل، نشانی IP یا هر شناسهٔ حساب و دستگاه را ثبت نمی‌کنیم و چیزی نمی‌گذاریم که اگر بازگردید شما را بشناسیم.","چرا","این آزمون هنوز نمونهٔ هنجاریابی ندارد. داده‌های پاسخ تنها راه سنجش این است که هر معما واقعاً چقدر دشوار است و چقدر استدلال قوی را از ضعیف جدا می‌کند؛ همین است که نمره‌ای به‌ظاهر معقول را به نمره‌ای معنادار بدل می‌کند. برای هیچ کار دیگری استفاده نمی‌شود و هرگز فروخته نمی‌شود.","کوکی‌ها و ذخیره‌سازی محلی","انتخاب پوسته و زبان شما را در حافظهٔ محلی مرورگرتان نگه می‌داریم. چیز دیگری روی دستگاه شما نمی‌نویسیم.","تبلیغات","از Google AdSense استفاده می‌کنیم. گوگل ممکن است کوکی بگذارد و از آن برای نمایش آگهی مرتبط بهره ببرد. %s گوگل را ببینید.","تحلیل بازدید","از Google Analytics استفاده می‌کنیم تا ببینیم کدام صفحه‌ها بازدید می‌شوند. گوگل این را با شرایط خودش جمع می‌کند، از جمله موقعیت تقریبی و نوع دستگاه.","داده‌های شما","چون سوابق آزمون هیچ چیزی ندارند که شما را بشناساند، نمی‌توانیم رکورد یک فرد مشخص را بیابیم، صادر یا حذف کنیم؛ هیچ پیوندی به شما وجود ندارد. اگر ترجیح می‌دهید چیزی جمع نشود، کافی است آزمون را تمام نکنید: تا پیش از نمایش نتیجه چیزی ارسال نمی‌شود.","تماس"],
"fi": ["Mitä keräämme","Kun päätät ÄO- tai kuviotestin, kirjaamme miten se meni: mitkä tehtäväsäännöt esiintyivät, vastattiinko kuhunkin oikein, kuinka kauan kukin kesti, kokonaispisteesi, kielesi ja päivämäärän. Emme kirjaa nimeä, sähköpostia, IP-osoitetta emmekä mitään tili- tai laitetunnistetta, emmekä tallenna mitään, jonka perusteella tunnistaisimme sinut palatessasi.","Miksi","Testillä ei vielä ole normitusotosta. Vastausdata on ainoa tapa mitata, kuinka vaikea kukin tehtävä todella on ja kuinka hyvin se erottaa vahvan päättelyn heikosta — juuri se tekee uskottavan näköisestä pistemäärästä merkityksellisen. Sitä ei käytetä mihinkään muuhun eikä koskaan myydä.","Evästeet ja paikallinen tallennus","Säilytämme teema- ja kielivalintasi selaimen paikallisessa tallennuksessa. Muuta emme kirjoita laitteellesi.","Mainonta","Käytämme Google AdSensea. Google voi asettaa evästeitä ja käyttää niitä osuvien mainosten näyttämiseen. Katso Googlen %s.","Analytiikka","Käytämme Google Analyticsia nähdäksemme, mitä sivuja käydään katsomassa. Google kerää sen omilla ehdoillaan, mukaan lukien likimääräinen sijainti ja laitetyyppi.","Tietosi","Koska testitietueissa ei ole mitään sinua yksilöivää, emme voi löytää, viedä tai poistaa yksittäisen ihmisen merkintää — yhteyttä sinuun ei ole. Jos et halua mitään kerättävän, älä vie testiä loppuun: mitään ei lähetetä ennen kuin tuloksesi ilmestyy.","Yhteystiedot"],
"fr": ["Ce que nous collectons","Lorsque vous terminez le test de QI ou de motifs, nous enregistrons son déroulement : quelles règles de puzzle sont apparues, si chacune a été résolue, le temps passé sur chacune, votre score total, votre langue et la date. Nous n'enregistrons ni nom, ni e-mail, ni adresse IP, ni identifiant de compte ou d'appareil, et nous ne conservons rien qui nous permettrait de vous reconnaître à votre retour.","Pourquoi","Ce test n'a pas encore d'échantillon d'étalonnage. Les données de réponse sont le seul moyen de mesurer la difficulté réelle de chaque puzzle et sa capacité à séparer un raisonnement fort d'un raisonnement faible — c'est ce qui transforme un score plausible en score significatif. Elles ne servent à rien d'autre et ne sont jamais vendues.","Cookies et stockage local","Nous gardons votre choix de thème et de langue dans le stockage local du navigateur. Nous n'écrivons rien d'autre sur votre appareil.","Publicité","Nous utilisons Google AdSense. Google peut déposer des cookies et s'en servir pour afficher des annonces pertinentes. Voir la %s de Google.","Analyse d'audience","Nous utilisons Google Analytics pour voir quelles pages sont consultées. Google collecte cela selon ses propres conditions, y compris la localisation approximative et le type d'appareil.","Vos données","Comme les enregistrements de test ne contiennent rien qui vous identifie, nous ne pouvons ni retrouver, ni exporter, ni supprimer l'entrée d'une personne précise : aucun lien ne remonte jusqu'à vous. Si vous préférez que rien ne soit collecté, ne terminez simplement pas le test : rien n'est envoyé avant l'affichage de votre résultat.","Contact"],
"he": ["מה אנחנו אוספים","כשאתם מסיימים את מבחן האינטליגנציה או מבחן התבניות, אנחנו רושמים איך הוא התנהל: אילו כללי חידה הופיעו, האם כל אחת נענתה נכון, כמה זמן לקחה כל אחת, הציון הכולל, השפה והתאריך. איננו רושמים שם, אימייל, כתובת IP או מזהה חשבון או מכשיר, ואיננו שומרים דבר שיאפשר לנו לזהות אתכם אם תחזרו.","למה","למבחן הזה אין עדיין מדגם תקנון. נתוני התשובות הם הדרך היחידה למדוד כמה כל חידה באמת קשה וכמה טוב היא מפרידה חשיבה חזקה מחלשה — וזה מה שהופך ציון סביר למשמעותי. הם אינם משמשים לשום דבר אחר ולעולם אינם נמכרים.","עוגיות ואחסון מקומי","אנחנו שומרים את בחירת ערכת הנושא והשפה באחסון המקומי של הדפדפן. שום דבר אחר לא נכתב למכשיר שלכם.","פרסום","אנחנו משתמשים ב-Google AdSense. גוגל עשויה להציב עוגיות ולהשתמש בהן להצגת מודעות רלוונטיות. ראו את %s של גוגל.","אנליטיקה","אנחנו משתמשים ב-Google Analytics כדי לראות אילו עמודים נצפים. גוגל אוספת זאת לפי תנאיה שלה, כולל מיקום משוער וסוג מכשיר.","הנתונים שלכם","מכיוון שרשומות המבחן אינן מכילות דבר המזהה אתכם, איננו יכולים לאתר, לייצא או למחוק רשומה של אדם מסוים — אין קישור חזרה אליכם. אם אתם מעדיפים שדבר לא ייאסף, פשוט אל תסיימו את המבחן: שום דבר לא נשלח עד שהתוצאה מופיעה.","יצירת קשר"],
"hi": ["हम क्या एकत्र करते हैं","जब आप बुद्धि या पैटर्न परीक्षण पूरा करते हैं, हम दर्ज करते हैं कि वह कैसा रहा: कौन-से पहेली नियम आए, हर एक सही हुई या नहीं, हर एक में कितना समय लगा, आपका कुल अंक, आपकी भाषा और तारीख़। हम न नाम, न ईमेल, न IP पता, न कोई खाता या उपकरण पहचानकर्ता दर्ज करते हैं, और ऐसा कुछ नहीं रखते जिससे लौटने पर आपको पहचान सकें।","क्यों","इस परीक्षण का अभी कोई मानकीकरण नमूना नहीं है। उत्तरों का डेटा ही एकमात्र तरीका है यह मापने का कि हर पहेली वास्तव में कितनी कठिन है और वह मज़बूत तर्क को कमज़ोर से कितना अलग करती है — यही एक विश्वसनीय दिखने वाले अंक को अर्थपूर्ण बनाता है। इसका और कोई उपयोग नहीं होता और यह कभी बेचा नहीं जाता।","कुकीज़ और स्थानीय संग्रह","आपकी थीम और भाषा का चयन ब्राउज़र के स्थानीय संग्रह में रहता है। इसके अलावा हम आपके उपकरण पर कुछ नहीं लिखते।","विज्ञापन","हम Google AdSense का उपयोग करते हैं। Google कुकीज़ रख सकता है और प्रासंगिक विज्ञापन दिखाने के लिए उनका उपयोग कर सकता है। Google की %s देखें।","विश्लेषण","हम Google Analytics का उपयोग यह देखने के लिए करते हैं कि कौन-से पृष्ठ देखे जाते हैं। Google इसे अपनी शर्तों पर एकत्र करता है, जिसमें अनुमानित स्थान और उपकरण प्रकार शामिल हैं।","आपका डेटा","चूँकि परीक्षण अभिलेखों में आपकी पहचान वाला कुछ नहीं है, हम किसी एक व्यक्ति की प्रविष्टि खोज, निर्यात या मिटा नहीं सकते — आप तक कोई कड़ी नहीं है। यदि आप चाहते हैं कि कुछ भी एकत्र न हो, तो बस परीक्षण पूरा न करें: परिणाम दिखने से पहले कुछ नहीं भेजा जाता।","संपर्क"],
"hr": ["Što prikupljamo","Kada dovršite test inteligencije ili test uzoraka, bilježimo kako je prošao: koja su se pravila zadataka pojavila, je li svaki riješen točno, koliko je svaki trajao, vaš ukupni rezultat, jezik i datum. Ne bilježimo ime, e-poštu, IP adresu ni identifikator računa ili uređaja i ne pohranjujemo ništa po čemu bismo vas prepoznali pri povratku.","Zašto","Ovaj test još nema standardizacijski uzorak. Podaci o odgovorima jedini su način da izmjerimo koliko je svaki zadatak zaista težak i koliko dobro odvaja snažno zaključivanje od slabog — upravo to pretvara uvjerljiv rezultat u smislen. Ne koriste se ni za što drugo i nikada se ne prodaju.","Kolačići i lokalna pohrana","Vaš izbor teme i jezika čuvamo u lokalnoj pohrani preglednika. Ništa drugo ne zapisujemo na vaš uređaj.","Oglašavanje","Koristimo Google AdSense. Google može postaviti kolačiće i koristiti ih za prikaz relevantnih oglasa. Pogledajte Googleovu %s.","Analitika","Koristimo Google Analytics kako bismo vidjeli koje se stranice posjećuju. Google to prikuplja pod vlastitim uvjetima, uključujući približnu lokaciju i vrstu uređaja.","Vaši podaci","Budući da zapisi testa ne sadrže ništa što vas identificira, ne možemo pronaći, izvesti ni izbrisati unos pojedine osobe — ne postoji poveznica natrag do vas. Ako vam je draže da se ništa ne prikuplja, jednostavno nemojte dovršiti test: ništa se ne šalje dok se ne pojavi vaš rezultat.","Kontakt"],
"hu": ["Mit gyűjtünk","Amikor befejezi az IQ- vagy mintatesztet, rögzítjük, hogyan zajlott: mely feladatszabályok jelentek meg, mindegyikre helyes válasz érkezett-e, mennyi ideig tartott mindegyik, az összpontszámát, a nyelvét és a dátumot. Nem rögzítünk nevet, e-mailt, IP-címet, sem fiók- vagy eszközazonosítót, és semmit nem tárolunk, ami alapján visszatérve felismernénk.","Miért","Ennek a tesztnek még nincs standardizálási mintája. A válaszadatok az egyetlen módja megmérni, mennyire nehéz valójában egy-egy feladat, és mennyire választja el az erős gondolkodást a gyengétől — ez az, ami a hihetőnek látszó pontszámot értelmessé teszi. Semmi másra nem használjuk, és soha nem adjuk el.","Sütik és helyi tárolás","A téma- és nyelvválasztását a böngésző helyi tárolójában tartjuk. Ezen kívül semmit nem írunk az eszközére.","Hirdetés","Google AdSense-t használunk. A Google sütiket helyezhet el, és azokkal releváns hirdetéseket jeleníthet meg. Lásd a Google %s.","Analitika","Google Analyticsot használunk, hogy lássuk, mely oldalakat látogatják. A Google ezt saját feltételei szerint gyűjti, ideértve a hozzávetőleges helyet és az eszköztípust.","Az Ön adatai","Mivel a tesztrekordok semmit nem tartalmaznak, ami azonosítaná Önt, nem tudjuk megtalálni, exportálni vagy törölni egy adott személy bejegyzését — nincs visszavezető kapcsolat. Ha inkább semmit nem gyűjtenénk, egyszerűen ne fejezze be a tesztet: az eredmény megjelenéséig semmi nem kerül elküldésre.","Kapcsolat"],
"id": ["Apa yang kami kumpulkan","Saat Anda menyelesaikan tes IQ atau tes pola, kami mencatat bagaimana jalannya: aturan teka-teki apa yang muncul, apakah masing-masing dijawab benar, berapa lama tiap soal, skor total Anda, bahasa Anda, dan tanggalnya. Kami tidak mencatat nama, email, alamat IP, atau pengenal akun maupun perangkat, dan tidak menyimpan apa pun yang memungkinkan kami mengenali Anda bila kembali.","Mengapa","Tes ini belum punya sampel pembakuan. Data respons adalah satu-satunya cara mengukur seberapa sulit tiap teka-teki sebenarnya dan seberapa baik ia memisahkan penalaran kuat dari lemah — itulah yang mengubah skor yang tampak masuk akal menjadi bermakna. Tidak dipakai untuk hal lain dan tidak pernah dijual.","Kuki dan penyimpanan lokal","Pilihan tema dan bahasa Anda kami simpan di penyimpanan lokal peramban. Selain itu kami tidak menulis apa pun ke perangkat Anda.","Periklanan","Kami memakai Google AdSense. Google dapat memasang kuki dan memakainya untuk menampilkan iklan yang relevan. Lihat %s Google.","Analitik","Kami memakai Google Analytics untuk melihat halaman mana yang dikunjungi. Google mengumpulkannya menurut ketentuannya sendiri, termasuk perkiraan lokasi dan jenis perangkat.","Data Anda","Karena catatan tes tidak memuat apa pun yang mengidentifikasi Anda, kami tidak dapat menemukan, mengekspor, atau menghapus entri seseorang — tidak ada tautan kembali kepada Anda. Jika Anda lebih suka tidak ada yang dikumpulkan, cukup jangan selesaikan tesnya: tidak ada yang dikirim sebelum hasil Anda muncul.","Kontak"],
"it": ["Cosa raccogliamo","Quando concludi il test del QI o quello dei pattern registriamo com'è andato: quali regole di rompicapo sono comparse, se ciascuna è stata risolta, quanto è durata ognuna, il tuo punteggio totale, la lingua e la data. Non registriamo nome, email, indirizzo IP né alcun identificativo di account o dispositivo, e non conserviamo nulla che ci permetta di riconoscerti al ritorno.","Perché","Questo test non ha ancora un campione di standardizzazione. I dati di risposta sono l'unico modo per misurare quanto sia davvero difficile ogni rompicapo e quanto separi il ragionamento forte da quello debole: è ciò che trasforma un punteggio plausibile in uno significativo. Non servono ad altro e non vengono mai venduti.","Cookie e archiviazione locale","Teniamo la scelta di tema e lingua nell'archiviazione locale del browser. Nient'altro viene scritto sul tuo dispositivo.","Pubblicità","Usiamo Google AdSense. Google può impostare cookie e usarli per mostrare annunci pertinenti. Vedi la %s di Google.","Analisi","Usiamo Google Analytics per vedere quali pagine vengono visitate. Google lo raccoglie secondo i propri termini, inclusi posizione approssimativa e tipo di dispositivo.","I tuoi dati","Poiché i record del test non contengono nulla che ti identifichi, non possiamo trovare, esportare o cancellare la voce di una singola persona: non esiste un collegamento che risalga a te. Se preferisci che non venga raccolto nulla, semplicemente non completare il test: nulla viene inviato prima che compaia il risultato.","Contatti"],
"ja": ["収集する内容","知能検査またはパターン検査を終えると、その経過を記録します。どの規則の問題が出たか、それぞれ正解したか、各問にかかった時間、合計得点、言語、日付です。氏名、メールアドレス、IPアドレス、アカウントや端末の識別子は記録せず、再訪時にあなたを識別できるものも一切保存しません。","理由","この検査にはまだ標準化標本がありません。各問題が実際にどれだけ難しく、強い推理と弱い推理をどれだけ区別できるかを測る手段は回答データだけであり、それがもっともらしい得点を意味のある得点に変えます。他の用途には使わず、販売もしません。","Cookie とローカル保存","テーマと言語の選択をブラウザのローカル保存に保持します。それ以外に端末へ書き込むものはありません。","広告","Google AdSense を使用しています。Google が Cookie を設定し、関連性の高い広告の表示に利用する場合があります。Google の%sをご覧ください。","アクセス解析","どのページが見られているかを把握するため Google Analytics を使用しています。Google は同社の条件に基づき、おおよその位置や端末の種類を含めて収集します。","あなたのデータ","検査の記録にはあなたを特定できるものが含まれないため、特定の個人の記録を探し出すことも、書き出すことも、削除することもできません。あなたへ辿る手がかりが存在しないからです。何も収集されたくない場合は、検査を最後まで進めないでください。結果が表示されるまで何も送信されません。","お問い合わせ"],
"ko": ["수집하는 내용","지능 검사나 패턴 검사를 마치면 진행 상황을 기록합니다. 어떤 규칙의 문제가 나왔는지, 각 문항을 맞혔는지, 각 문항에 걸린 시간, 총점, 언어, 날짜입니다. 이름, 이메일, IP 주소, 계정이나 기기 식별자는 기록하지 않으며, 다시 방문했을 때 알아볼 수 있는 어떤 것도 저장하지 않습니다.","이유","이 검사에는 아직 표준화 표본이 없습니다. 각 문항이 실제로 얼마나 어려운지, 그리고 뛰어난 추론과 그렇지 않은 추론을 얼마나 잘 가려내는지 측정할 방법은 응답 데이터뿐이며, 바로 그것이 그럴듯해 보이는 점수를 의미 있는 점수로 만듭니다. 다른 용도로 쓰지 않고 판매하지도 않습니다.","쿠키와 로컬 저장소","테마와 언어 선택은 브라우저의 로컬 저장소에 보관합니다. 그 외에는 기기에 아무것도 기록하지 않습니다.","광고","Google AdSense를 사용합니다. Google이 쿠키를 설정하고 이를 관련 광고 노출에 사용할 수 있습니다. Google의 %s을 참고하세요.","분석","어떤 페이지가 방문되는지 확인하기 위해 Google Analytics를 사용합니다. Google은 자체 약관에 따라 대략적인 위치와 기기 유형을 포함해 수집합니다.","귀하의 데이터","검사 기록에는 귀하를 식별할 수 있는 내용이 없으므로, 특정 개인의 기록을 찾거나 내보내거나 삭제할 수 없습니다. 귀하로 되돌아갈 연결 고리가 없기 때문입니다. 아무것도 수집되지 않기를 원하신다면 검사를 끝까지 진행하지 마세요. 결과가 표시되기 전에는 아무것도 전송되지 않습니다.","문의"],
"lt": ["Ką renkame","Kai baigiate intelekto ar raštų testą, užrašome, kaip jis vyko: kokios užduočių taisyklės pasitaikė, ar į kiekvieną atsakyta teisingai, kiek laiko užtruko kiekviena, jūsų bendrą rezultatą, kalbą ir datą. Neužrašome vardo, el. pašto, IP adreso nei paskyros ar įrenginio identifikatoriaus ir nesaugome nieko, kas leistų jus atpažinti sugrįžus.","Kodėl","Šis testas dar neturi standartizavimo imties. Atsakymų duomenys yra vienintelis būdas išmatuoti, kiek kiekviena užduotis iš tikrųjų sunki ir kaip gerai ji atskiria stiprų mąstymą nuo silpno — būtent tai patikimai atrodantį rezultatą paverčia prasmingu. Jie nenaudojami niekam kitam ir niekada neparduodami.","Slapukai ir vietinė saugykla","Jūsų temos ir kalbos pasirinkimą laikome naršyklės vietinėje saugykloje. Daugiau nieko į jūsų įrenginį nerašome.","Reklama","Naudojame Google AdSense. Google gali įrašyti slapukus ir naudoti juos aktualioms reklamoms rodyti. Žr. Google %s.","Analitika","Naudojame Google Analytics, kad matytume, kurie puslapiai lankomi. Google tai renka savo sąlygomis, įskaitant apytikslę vietą ir įrenginio tipą.","Jūsų duomenys","Kadangi testo įrašuose nėra nieko, kas jus identifikuotų, negalime rasti, eksportuoti ar ištrinti konkretaus žmogaus įrašo — nėra jokios sąsajos su jumis. Jei nenorite, kad kas nors būtų renkama, tiesiog nebaikite testo: kol nepasirodo rezultatas, niekas nesiunčiama.","Kontaktai"],
"lv": ["Ko mēs vācam","Kad pabeidzat intelekta vai rakstu testu, mēs pierakstām, kā tas noritēja: kādi uzdevumu likumi parādījās, vai uz katru atbildēts pareizi, cik ilgi katrs prasīja, jūsu kopvērtējumu, valodu un datumu. Mēs nepierakstām vārdu, e-pastu, IP adresi vai konta un ierīces identifikatoru un neglabājam neko, kas ļautu jūs atpazīt atgriežoties.","Kāpēc","Šim testam vēl nav standartizācijas izlases. Atbilžu dati ir vienīgais veids, kā izmērīt, cik grūts katrs uzdevums patiesībā ir un cik labi tas nošķir spēcīgu spriešanu no vājas — tieši tas pārvērš ticami izskatīgu rezultātu jēgpilnā. Tos neizmanto nekam citam un nekad nepārdod.","Sīkdatnes un vietējā krātuve","Jūsu motīva un valodas izvēli glabājam pārlūka vietējā krātuvē. Neko citu jūsu ierīcē nerakstām.","Reklāma","Mēs izmantojam Google AdSense. Google var iestatīt sīkdatnes un izmantot tās atbilstošu reklāmu rādīšanai. Skatiet Google %s.","Analītika","Mēs izmantojam Google Analytics, lai redzētu, kuras lapas tiek apmeklētas. Google to vāc pēc saviem noteikumiem, tostarp aptuveno atrašanās vietu un ierīces veidu.","Jūsu dati","Tā kā testa ierakstos nav nekā, kas jūs identificētu, mēs nevaram atrast, eksportēt vai dzēst konkrētas personas ierakstu — nav saiknes atpakaļ uz jums. Ja vēlaties, lai nekas netiktu vākts, vienkārši nepabeidziet testu: līdz rezultāta parādīšanās brīdim nekas netiek nosūtīts.","Kontakti"],
"mk": ["Што собираме","Кога ќе го завршите тестот за интелигенција или тестот за обрасци, забележуваме како поминал: кои правила на задачите се појавиле, дали на секоја е одговорено точно, колку траела секоја, вашиот вкупен резултат, јазикот и датумот. Не забележуваме име, е-пошта, IP адреса ниту идентификатор на сметка или уред и не чуваме ништо што би ни овозможило да ве препознаеме при враќање.","Зошто","Овој тест сè уште нема стандардизациски примерок. Податоците од одговорите се единствениот начин да се измери колку е навистина тешка секоја задача и колку добро го одвојува силното од слабото расудување — токму тоа претвора уверлив резултат во значаен. Не се користат за ништо друго и никогаш не се продаваат.","Колачиња и локална меморија","Вашиот избор на тема и јазик го чуваме во локалната меморија на прелистувачот. Ништо друго не запишуваме на вашиот уред.","Рекламирање","Користиме Google AdSense. Google може да постави колачиња и да ги користи за прикажување релевантни реклами. Видете ја %s на Google.","Аналитика","Користиме Google Analytics за да видиме кои страници се посетуваат. Google го собира тоа под свои услови, вклучувајќи приближна локација и тип на уред.","Вашите податоци","Бидејќи записите од тестот не содржат ништо што ве идентификува, не можеме да го најдеме, извеземе или избришеме записот на определено лице — не постои врска назад до вас. Ако претпочитате ништо да не се собира, едноставно не го завршувајте тестот: ништо не се испраќа пред да се појави вашиот резултат.","Контакт"],
"ms": ["Apa yang kami kumpul","Apabila anda menyelesaikan ujian IQ atau ujian corak, kami merekod bagaimana ia berjalan: peraturan teka-teki yang muncul, sama ada setiap satu dijawab betul, berapa lama setiap satu diambil, jumlah skor anda, bahasa anda dan tarikhnya. Kami tidak merekod nama, e-mel, alamat IP, atau sebarang pengecam akaun atau peranti, dan kami tidak menyimpan apa-apa yang membolehkan kami mengenali anda jika anda kembali.","Mengapa","Ujian ini belum mempunyai sampel pemiawaian. Data respons ialah satu-satunya cara mengukur betapa sukarnya setiap teka-teki sebenarnya dan sebaik mana ia memisahkan penaakulan kuat daripada lemah — itulah yang menjadikan skor yang kelihatan munasabah bermakna. Ia tidak digunakan untuk apa-apa lain dan tidak pernah dijual.","Kuki dan storan setempat","Pilihan tema dan bahasa anda disimpan dalam storan setempat pelayar. Kami tidak menulis apa-apa lagi ke peranti anda.","Pengiklanan","Kami menggunakan Google AdSense. Google mungkin menetapkan kuki dan menggunakannya untuk memaparkan iklan yang berkaitan. Lihat %s Google.","Analitik","Kami menggunakan Google Analytics untuk melihat halaman mana yang dilawati. Google mengumpulnya mengikut terma sendiri, termasuk lokasi anggaran dan jenis peranti.","Data anda","Oleh sebab rekod ujian tidak mengandungi apa-apa yang mengenal pasti anda, kami tidak dapat mencari, mengeksport atau memadam entri seseorang individu — tiada pautan kembali kepada anda. Jika anda lebih suka tiada apa-apa dikumpul, jangan selesaikan ujian: tiada apa dihantar sebelum keputusan anda muncul.","Hubungi"],
"nl": ["Wat we verzamelen","Als je de IQ- of patroontest afrondt, leggen we vast hoe het ging: welke puzzelregels voorkwamen, of elke goed werd beantwoord, hoe lang elke duurde, je totaalscore, je taal en de datum. We leggen geen naam, e-mail, IP-adres of account- of apparaat-identificatie vast, en we bewaren niets waarmee we je bij terugkomst zouden herkennen.","Waarom","Deze test heeft nog geen normeringssteekproef. Antwoorddata zijn de enige manier om te meten hoe moeilijk elke puzzel werkelijk is en hoe goed die sterk van zwak redeneren scheidt — dat maakt van een aannemelijk ogende score een betekenisvolle. Ze worden nergens anders voor gebruikt en nooit verkocht.","Cookies en lokale opslag","Je keuze voor thema en taal bewaren we in de lokale opslag van je browser. Verder schrijven we niets naar je apparaat.","Advertenties","We gebruiken Google AdSense. Google kan cookies plaatsen en die gebruiken om relevante advertenties te tonen. Zie Googles %s.","Analyse","We gebruiken Google Analytics om te zien welke pagina's worden bezocht. Google verzamelt dat onder eigen voorwaarden, waaronder globale locatie en apparaattype.","Jouw gegevens","Omdat de testrecords niets bevatten dat jou identificeert, kunnen we de invoer van een individuele persoon niet vinden, exporteren of verwijderen — er is geen link terug naar jou. Wil je liever dat er niets wordt verzameld, maak de test dan simpelweg niet af: er wordt niets verzonden voordat je resultaat verschijnt.","Contact"],
"no": ["Hva vi samler inn","Når du fullfører IQ- eller mønstertesten, registrerer vi hvordan det gikk: hvilke oppgaveregler som dukket opp, om hver ble besvart riktig, hvor lang tid hver tok, totalskåren din, språket ditt og datoen. Vi registrerer ikke navn, e-post, IP-adresse eller noen konto- eller enhets-ID, og vi lagrer ingenting som ville latt oss kjenne deg igjen om du kommer tilbake.","Hvorfor","Testen har ennå ingen normeringsutvalg. Svardata er den eneste måten å måle hvor vanskelig hver oppgave faktisk er, og hvor godt den skiller sterk resonnering fra svak — det er dette som gjør en troverdig skår meningsfull. De brukes ikke til noe annet og selges aldri.","Informasjonskapsler og lokal lagring","Valget ditt av tema og språk ligger i nettleserens lokale lagring. Vi skriver ingenting annet til enheten din.","Annonsering","Vi bruker Google AdSense. Google kan sette informasjonskapsler og bruke dem til å vise relevante annonser. Se Googles %s.","Analyse","Vi bruker Google Analytics for å se hvilke sider som besøkes. Google samler dette på egne vilkår, inkludert omtrentlig plassering og enhetstype.","Dine data","Fordi testoppføringene ikke inneholder noe som identifiserer deg, kan vi ikke finne, eksportere eller slette en enkeltpersons oppføring — det finnes ingen kobling tilbake til deg. Foretrekker du at ingenting samles inn, la være å fullføre testen: ingenting sendes før resultatet ditt vises.","Kontakt"],
"pl": ["Co zbieramy","Gdy kończysz test inteligencji lub test wzorów, zapisujemy jego przebieg: jakie reguły zadań wystąpiły, czy każde zostało rozwiązane poprawnie, ile trwało każde, twój wynik łączny, język i datę. Nie zapisujemy imienia, adresu e-mail, adresu IP ani żadnego identyfikatora konta czy urządzenia i nie przechowujemy niczego, co pozwoliłoby nam rozpoznać cię przy powrocie.","Dlaczego","Ten test nie ma jeszcze próby normalizacyjnej. Dane odpowiedzi to jedyny sposób, by zmierzyć, jak trudne naprawdę jest każde zadanie i jak dobrze oddziela mocne rozumowanie od słabego — to właśnie zmienia wiarygodnie wyglądający wynik w wynik znaczący. Nie służą do niczego innego i nigdy nie są sprzedawane.","Pliki cookie i pamięć lokalna","Twój wybór motywu i języka trzymamy w pamięci lokalnej przeglądarki. Niczego więcej nie zapisujemy na twoim urządzeniu.","Reklama","Korzystamy z Google AdSense. Google może ustawiać pliki cookie i używać ich do wyświetlania trafnych reklam. Zobacz %s Google.","Analityka","Korzystamy z Google Analytics, aby widzieć, które strony są odwiedzane. Google zbiera to na własnych warunkach, w tym przybliżoną lokalizację i typ urządzenia.","Twoje dane","Ponieważ zapisy testu nie zawierają niczego, co by cię identyfikowało, nie możemy odnaleźć, wyeksportować ani usunąć wpisu konkretnej osoby — nie istnieje powiązanie prowadzące do ciebie. Jeśli wolisz, by nic nie było zbierane, po prostu nie kończ testu: nic nie jest wysyłane, zanim pojawi się wynik.","Kontakt"],
"pt": ["O que recolhemos","Quando termina o teste de QI ou o de padrões, registamos como correu: que regras de puzzle surgiram, se cada uma foi respondida corretamente, quanto tempo demorou cada uma, a sua pontuação total, o idioma e a data. Não registamos nome, email, endereço IP nem qualquer identificador de conta ou dispositivo, e não guardamos nada que nos permitisse reconhecê-lo se voltasse.","Porquê","Este teste ainda não tem amostra de aferição. Os dados de resposta são a única forma de medir quão difícil cada puzzle realmente é e quão bem separa o raciocínio forte do fraco — é isso que transforma uma pontuação plausível numa pontuação significativa. Não são usados para mais nada e nunca são vendidos.","Cookies e armazenamento local","Guardamos a sua escolha de tema e idioma no armazenamento local do navegador. Nada mais é escrito no seu dispositivo.","Publicidade","Usamos o Google AdSense. A Google pode colocar cookies e usá-los para mostrar anúncios relevantes. Consulte a %s da Google.","Estatísticas","Usamos o Google Analytics para ver que páginas são visitadas. A Google recolhe isso segundo os seus próprios termos, incluindo localização aproximada e tipo de dispositivo.","Os seus dados","Como os registos do teste não contêm nada que o identifique, não conseguimos localizar, exportar ou apagar a entrada de uma pessoa específica — não existe ligação de volta a si. Se prefere que nada seja recolhido, simplesmente não termine o teste: nada é enviado antes de o resultado aparecer.","Contacto"],
"ro": ["Ce colectăm","Când termini testul de inteligență sau cel de tipare, înregistrăm cum a decurs: ce reguli de puzzle au apărut, dacă fiecare a primit răspuns corect, cât a durat fiecare, scorul tău total, limba și data. Nu înregistrăm nume, email, adresă IP și niciun identificator de cont sau dispozitiv, și nu păstrăm nimic care să ne permită să te recunoaștem la o revenire.","De ce","Acest test nu are încă un eșantion de etalonare. Datele de răspuns sunt singura cale de a măsura cât de greu este cu adevărat fiecare puzzle și cât de bine separă raționamentul puternic de cel slab — asta transformă un scor plauzibil într-unul cu sens. Nu sunt folosite pentru altceva și nu sunt niciodată vândute.","Cookie-uri și stocare locală","Păstrăm alegerea ta de temă și limbă în stocarea locală a browserului. Nimic altceva nu scriem pe dispozitivul tău.","Publicitate","Folosim Google AdSense. Google poate seta cookie-uri și le poate folosi pentru a afișa reclame relevante. Vezi %s Google.","Analiză","Folosim Google Analytics ca să vedem ce pagini sunt vizitate. Google colectează asta în termenii proprii, inclusiv locația aproximativă și tipul dispozitivului.","Datele tale","Deoarece înregistrările testului nu conțin nimic care să te identifice, nu putem găsi, exporta sau șterge intrarea unei anumite persoane — nu există nicio legătură înapoi la tine. Dacă preferi să nu se colecteze nimic, pur și simplu nu termina testul: nimic nu se trimite până nu apare rezultatul.","Contact"],
"ru": ["Что мы собираем","Когда вы завершаете тест интеллекта или тест закономерностей, мы записываем, как он прошёл: какие правила задач встретились, решена ли каждая верно, сколько заняла каждая, ваш общий балл, язык и дату. Мы не записываем имя, почту, IP-адрес и никакие идентификаторы аккаунта или устройства, и не сохраняем ничего, по чему узнали бы вас при возвращении.","Зачем","У этого теста пока нет нормативной выборки. Данные ответов — единственный способ измерить, насколько каждая задача трудна на деле и насколько хорошо она отделяет сильное мышление от слабого; именно это превращает правдоподобный балл в осмысленный. Ни для чего другого они не используются и никогда не продаются.","Файлы cookie и локальное хранилище","Ваш выбор темы и языка хранится в локальном хранилище браузера. Больше мы ничего на ваше устройство не пишем.","Реклама","Мы используем Google AdSense. Google может устанавливать cookie и применять их для показа релевантной рекламы. См. %s Google.","Аналитика","Мы используем Google Analytics, чтобы видеть, какие страницы посещают. Google собирает это на своих условиях, включая приблизительное местоположение и тип устройства.","Ваши данные","Поскольку записи теста не содержат ничего, что вас идентифицирует, мы не можем найти, выгрузить или удалить запись конкретного человека — связи с вами не существует. Если вы предпочитаете, чтобы ничего не собиралось, просто не завершайте тест: до появления результата ничего не отправляется.","Контакты"],
"sk": ["Čo zbierame","Keď dokončíte test IQ alebo test vzorov, zaznamenáme, ako prebiehal: ktoré pravidlá úloh sa objavili, či bola každá zodpovedaná správne, ako dlho každá trvala, váš celkový výsledok, jazyk a dátum. Nezaznamenávame meno, e-mail, IP adresu ani žiadny identifikátor účtu či zariadenia a neukladáme nič, podľa čoho by sme vás pri návrate spoznali.","Prečo","Tento test zatiaľ nemá štandardizačnú vzorku. Údaje z odpovedí sú jediný spôsob, ako zmerať, aká ťažká je každá úloha v skutočnosti a ako dobre oddeľuje silné uvažovanie od slabého — práve to premieňa vierohodne vyzerajúce skóre na zmysluplné. Na nič iné sa nepoužívajú a nikdy sa nepredávajú.","Cookies a lokálne úložisko","Váš výber motívu a jazyka držíme v lokálnom úložisku prehliadača. Nič iné na vaše zariadenie nezapisujeme.","Reklama","Používame Google AdSense. Google môže nastaviť cookies a použiť ich na zobrazenie relevantných reklám. Pozrite %s spoločnosti Google.","Analytika","Používame Google Analytics, aby sme videli, ktoré stránky sa navštevujú. Google to zbiera podľa vlastných podmienok vrátane približnej polohy a typu zariadenia.","Vaše údaje","Keďže záznamy testu neobsahujú nič, čo by vás identifikovalo, nedokážeme nájsť, exportovať ani vymazať záznam konkrétnej osoby — neexistuje väzba späť na vás. Ak si neželáte, aby sa čokoľvek zbieralo, jednoducho test nedokončite: kým sa neobjaví výsledok, nič sa neodosiela.","Kontakt"],
"sl": ["Kaj zbiramo","Ko končate test inteligentnosti ali test vzorcev, zabeležimo, kako je potekal: katera pravila nalog so se pojavila, ali je bila vsaka rešena pravilno, koliko časa je vzela vsaka, vaš skupni rezultat, jezik in datum. Ne beležimo imena, e-pošte, naslova IP ali identifikatorja računa oziroma naprave in ne hranimo ničesar, po čemer bi vas ob vrnitvi prepoznali.","Zakaj","Ta test še nima standardizacijskega vzorca. Podatki o odgovorih so edini način, da izmerimo, kako težka je vsaka naloga v resnici in kako dobro loči močno sklepanje od šibkega — prav to spremeni verjeten videz rezultata v smiseln rezultat. Ne uporabljajo se za nič drugega in se nikoli ne prodajajo.","Piškotki in lokalna shramba","Vašo izbiro teme in jezika hranimo v lokalni shrambi brskalnika. Ničesar drugega ne zapisujemo na vašo napravo.","Oglaševanje","Uporabljamo Google AdSense. Google lahko nastavi piškotke in jih uporabi za prikaz ustreznih oglasov. Glejte Googlovo %s.","Analitika","Uporabljamo Google Analytics, da vidimo, katere strani se obiskujejo. Google to zbira pod svojimi pogoji, vključno s približno lokacijo in vrsto naprave.","Vaši podatki","Ker zapisi testa ne vsebujejo ničesar, kar bi vas identificiralo, ne moremo najti, izvoziti ali izbrisati vnosa posamezne osebe — povezave nazaj do vas ni. Če vam je ljubše, da se ne zbira nič, testa preprosto ne dokončajte: nič se ne pošlje, dokler se ne prikaže vaš rezultat.","Stik"],
"sq": ["Çfarë mbledhim","Kur përfundoni testin e inteligjencës ose atë të modeleve, regjistrojmë si shkoi: cilat rregulla enigmash u shfaqën, nëse secila u përgjigj saktë, sa zgjati secila, rezultatin tuaj total, gjuhën dhe datën. Nuk regjistrojmë emër, email, adresë IP apo ndonjë identifikues llogarie ose pajisjeje, dhe nuk ruajmë asgjë që do të na lejonte t'ju njihnim nëse ktheheni.","Pse","Ky test ende nuk ka kampion standardizimi. Të dhënat e përgjigjeve janë e vetmja mënyrë për të matur sa e vështirë është vërtet secila enigmë dhe sa mirë ndan arsyetimin e fortë nga i dobëti — kjo e kthen një rezultat me pamje të besueshme në një rezultat kuptimplotë. Nuk përdoren për asgjë tjetër dhe nuk shiten kurrë.","Cookies dhe ruajtja lokale","Zgjedhjen tuaj të temës dhe gjuhës e mbajmë në ruajtjen lokale të shfletuesit. Asgjë tjetër nuk shkruajmë në pajisjen tuaj.","Reklamat","Përdorim Google AdSense. Google mund të vendosë cookies dhe t'i përdorë për të shfaqur reklama të përshtatshme. Shihni %s e Google.","Analitika","Përdorim Google Analytics për të parë cilat faqe vizitohen. Google e mbledh këtë sipas kushteve të veta, përfshirë vendndodhjen e përafërt dhe llojin e pajisjes.","Të dhënat tuaja","Meqë të dhënat e testit nuk përmbajnë asgjë që ju identifikon, nuk mund të gjejmë, eksportojmë apo fshijmë shënimin e një personi të caktuar — nuk ka lidhje kthyese te ju. Nëse preferoni që të mos mblidhet asgjë, thjesht mos e përfundoni testin: asgjë nuk dërgohet para se të shfaqet rezultati juaj.","Kontakt"],
"sr": ["Шта прикупљамо","Када завршите тест интелигенције или тест образаца, бележимо како је протекао: која правила задатака су се појавила, да ли је на свако тачно одговорено, колико је свако трајало, ваш укупни резултат, језик и датум. Не бележимо име, мејл, IP адресу нити било какав идентификатор налога или уређаја и не чувамо ништа што би нам омогућило да вас препознамо при повратку.","Зашто","Овај тест још нема стандардизациони узорак. Подаци о одговорима су једини начин да се измери колико је сваки задатак заиста тежак и колико добро раздваја снажно закључивање од слабог — управо то претвара уверљив резултат у смислен. Не користе се ни за шта друго и никада се не продају.","Колачићи и локална меморија","Ваш избор теме и језика чувамо у локалној меморији прегледача. Ништа друго не уписујемо на ваш уређај.","Оглашавање","Користимо Google AdSense. Google може да постави колачиће и да их користи за приказ релевантних огласа. Погледајте Google-ову %s.","Аналитика","Користимо Google Analytics да видимо које се странице посећују. Google то прикупља под сопственим условима, укључујући приближну локацију и тип уређаја.","Ваши подаци","Пошто записи теста не садрже ништа што вас идентификује, не можемо да пронађемо, извеземо ни обришемо запис одређене особе — не постоји веза назад до вас. Ако више волите да се ништа не прикупља, једноставно немојте завршити тест: ништа се не шаље док се не појави ваш резултат.","Контакт"],
"sv": ["Vad vi samlar in","När du avslutar IQ- eller mönstertestet registrerar vi hur det gick: vilka uppgiftsregler som dök upp, om var och en besvarades rätt, hur lång tid var och en tog, din totalpoäng, ditt språk och datumet. Vi registrerar inte namn, e-post, IP-adress eller något konto- eller enhets-ID, och vi sparar inget som skulle låta oss känna igen dig vid ett återbesök.","Varför","Testet har ännu inget normeringsurval. Svarsdata är enda sättet att mäta hur svår varje uppgift faktiskt är och hur väl den skiljer starkt resonemang från svagt — det är det som gör ett trovärdigt utseende värde meningsfullt. De används inte till något annat och säljs aldrig.","Kakor och lokal lagring","Ditt val av tema och språk ligger i webbläsarens lokala lagring. Inget annat skrivs till din enhet.","Annonsering","Vi använder Google AdSense. Google kan sätta kakor och använda dem för att visa relevanta annonser. Se Googles %s.","Analys","Vi använder Google Analytics för att se vilka sidor som besöks. Google samlar in det på sina egna villkor, inklusive ungefärlig plats och enhetstyp.","Dina uppgifter","Eftersom testposterna inte innehåller något som identifierar dig kan vi inte hitta, exportera eller radera en enskild persons post — det finns ingen länk tillbaka till dig. Föredrar du att inget samlas in, avsluta helt enkelt inte testet: inget skickas innan ditt resultat visas.","Kontakt"],
"sw": ["Tunachokusanya","Unapomaliza kipimo cha akili au cha mifumo, tunarekodi jinsi kilivyokwenda: kanuni zipi za mafumbo zilitokea, kama kila moja ilijibiwa sahihi, kila moja ilichukua muda gani, alama yako jumla, lugha yako na tarehe. Haturekodi jina, barua pepe, anwani ya IP, wala kitambulisho chochote cha akaunti au kifaa, na hatuhifadhi chochote kitakachotuwezesha kukutambua ukirudi.","Kwa nini","Kipimo hiki bado hakina sampuli ya usawazishaji. Data ya majibu ndiyo njia pekee ya kupima ugumu halisi wa kila fumbo na jinsi linavyotenganisha ufikiri imara na dhaifu — hilo ndilo linalogeuza alama inayoonekana ya kuaminika kuwa yenye maana. Haitumiki kwa jambo jingine na haiuzwi kamwe.","Vidakuzi na hifadhi ya ndani","Chaguo lako la mandhari na lugha tunaliweka katika hifadhi ya ndani ya kivinjari. Hatuandiki kingine kwenye kifaa chako.","Matangazo","Tunatumia Google AdSense. Google inaweza kuweka vidakuzi na kuvitumia kuonyesha matangazo yanayofaa. Angalia %s ya Google.","Uchanganuzi","Tunatumia Google Analytics kuona kurasa zipi zinatembelewa. Google hukusanya hilo kwa masharti yake yenyewe, ikiwa ni pamoja na eneo la takriban na aina ya kifaa.","Data yako","Kwa kuwa kumbukumbu za kipimo hazina chochote kinachokutambulisha, hatuwezi kupata, kuhamisha au kufuta kumbukumbu ya mtu binafsi — hakuna kiungo kinachorudi kwako. Ikiwa unapendelea kutokusanywa kwa chochote, usimalize kipimo: hakuna kinachotumwa kabla matokeo yako hayajaonekana.","Wasiliana"],
"th": ["เราเก็บอะไรบ้าง","เมื่อคุณทำแบบทดสอบเชาวน์ปัญญาหรือแบบทดสอบรูปแบบจนจบ เราบันทึกว่าการทำเป็นอย่างไร ได้แก่ กฎของโจทย์ที่ปรากฏ แต่ละข้อตอบถูกหรือไม่ ใช้เวลาข้อละเท่าใด คะแนนรวม ภาษา และวันที่ เราไม่บันทึกชื่อ อีเมล ที่อยู่ IP หรือรหัสบัญชีและอุปกรณ์ใด ๆ และไม่เก็บสิ่งใดที่จะทำให้จำคุณได้หากกลับมาอีก","เพราะอะไร","แบบทดสอบนี้ยังไม่มีกลุ่มตัวอย่างสำหรับสร้างเกณฑ์ปกติ ข้อมูลการตอบเป็นวิธีเดียวที่จะวัดว่าแต่ละโจทย์ยากเพียงใดจริง ๆ และแยกการให้เหตุผลที่ดีออกจากที่อ่อนได้ดีแค่ไหน ซึ่งเป็นสิ่งที่เปลี่ยนคะแนนที่ดูน่าเชื่อให้กลายเป็นคะแนนที่มีความหมาย ข้อมูลนี้ไม่ถูกใช้เพื่อการอื่นและไม่เคยถูกขาย","คุกกี้และที่จัดเก็บในเครื่อง","เราเก็บการเลือกธีมและภาษาไว้ในที่จัดเก็บภายในเบราว์เซอร์ของคุณ นอกจากนี้เราไม่เขียนสิ่งใดลงอุปกรณ์ของคุณ","โฆษณา","เราใช้ Google AdSense กูเกิลอาจตั้งคุกกี้และใช้เพื่อแสดงโฆษณาที่เกี่ยวข้อง ดู%sของกูเกิล","การวิเคราะห์","เราใช้ Google Analytics เพื่อดูว่าหน้าใดมีผู้เข้าชม กูเกิลเก็บข้อมูลนี้ตามเงื่อนไขของตนเอง ซึ่งรวมถึงตำแหน่งโดยประมาณและชนิดอุปกรณ์","ข้อมูลของคุณ","เนื่องจากบันทึกการทำแบบทดสอบไม่มีสิ่งใดที่ระบุตัวคุณ เราจึงไม่สามารถค้นหา ส่งออก หรือลบรายการของบุคคลใดบุคคลหนึ่งได้ เพราะไม่มีสิ่งเชื่อมโยงกลับมาที่คุณ หากคุณไม่ต้องการให้เก็บสิ่งใดเลย เพียงไม่ต้องทำแบบทดสอบจนจบ ไม่มีการส่งข้อมูลใดก่อนที่ผลจะปรากฏ","ติดต่อ"],
"tl": ["Ano ang kinokolekta namin","Kapag natapos mo ang pagsusulit sa katalinuhan o sa pattern, itinatala namin kung paano ito naganap: anong mga panuntunan ng palaisipan ang lumabas, kung tama ang sagot sa bawat isa, gaano katagal ang bawat isa, ang kabuuang iskor mo, ang wika mo, at ang petsa. Hindi namin itinatala ang pangalan, email, IP address, o anumang pagkakakilanlan ng account o device, at wala kaming iniimbak na makapagpapakilala sa iyo kung babalik ka.","Bakit","Wala pang sampol na pamantayan ang pagsusulit na ito. Ang datos ng sagot lang ang paraan para masukat kung gaano talaga kahirap ang bawat palaisipan at gaano nito naihihiwalay ang matalas sa mahinang pangangatwiran — iyon ang gumagawa sa isang kapani-paniwalang iskor na makahulugan. Hindi ito ginagamit sa iba at hindi kailanman ibinebenta.","Cookies at lokal na imbakan","Ang piniling tema at wika mo ay nasa lokal na imbakan ng browser. Wala kaming ibang isinusulat sa device mo.","Advertising","Gumagamit kami ng Google AdSense. Maaaring maglagay ang Google ng cookies at gamitin ang mga ito para magpakita ng kaugnay na ad. Tingnan ang %s ng Google.","Analytics","Gumagamit kami ng Google Analytics para makita kung anong pahina ang binibisita. Kinokolekta ito ng Google sa sarili nitong mga tuntunin, kasama ang tinatayang lokasyon at uri ng device.","Ang datos mo","Dahil walang laman ang mga tala ng pagsusulit na makapagpapakilala sa iyo, hindi namin mahahanap, ma-e-export, o mabubura ang tala ng isang partikular na tao — walang kawing pabalik sa iyo. Kung mas gusto mong walang makolekta, huwag mo na lang tapusin ang pagsusulit: walang naipapadala hangga't hindi lumalabas ang resulta mo.","Kontak"],
"tr": ["Ne topluyoruz","Zeka testini veya örüntü testini bitirdiğinizde nasıl geçtiğini kaydediyoruz: hangi bulmaca kuralları çıktı, her biri doğru yanıtlandı mı, her biri ne kadar sürdü, toplam puanınız, diliniz ve tarih. Ad, e-posta, IP adresi ya da herhangi bir hesap veya cihaz tanımlayıcısı kaydetmiyoruz ve tekrar geldiğinizde sizi tanımamızı sağlayacak hiçbir şey saklamıyoruz.","Neden","Bu testin henüz bir standardizasyon örneklemi yok. Yanıt verileri, her bulmacanın gerçekte ne kadar zor olduğunu ve güçlü muhakemeyi zayıftan ne kadar iyi ayırdığını ölçmenin tek yolu; makul görünen bir puanı anlamlı bir puana dönüştüren de budur. Başka hiçbir şey için kullanılmaz ve asla satılmaz.","Çerezler ve yerel depolama","Tema ve dil seçiminizi tarayıcınızın yerel depolamasında tutuyoruz. Cihazınıza başka bir şey yazmıyoruz.","Reklam","Google AdSense kullanıyoruz. Google çerez yerleştirebilir ve bunları ilgili reklamları göstermek için kullanabilir. Google'ın %s bakın.","Analitik","Hangi sayfaların ziyaret edildiğini görmek için Google Analytics kullanıyoruz. Google bunu kendi koşullarına göre toplar; buna yaklaşık konum ve cihaz türü dahildir.","Verileriniz","Test kayıtları sizi tanımlayacak hiçbir şey içermediğinden, belirli bir kişinin kaydını bulamayız, dışa aktaramayız veya silemeyiz — size geri götüren bir bağ yok. Hiçbir şeyin toplanmamasını tercih ederseniz testi bitirmeyin: sonucunuz görünene dek hiçbir şey gönderilmez.","İletişim"],
"uk": ["Що ми збираємо","Коли ви завершуєте тест інтелекту або тест закономірностей, ми записуємо, як він минув: які правила задач траплялися, чи на кожну відповіли правильно, скільки часу зайняла кожна, ваш загальний бал, мову та дату. Ми не записуємо ім'я, пошту, IP-адресу чи будь-який ідентифікатор акаунта або пристрою і не зберігаємо нічого, за чим упізнали б вас під час повернення.","Навіщо","Цей тест поки не має нормувальної вибірки. Дані відповідей — єдиний спосіб виміряти, наскільки кожна задача справді складна і наскільки добре вона відрізняє сильне мислення від слабкого; саме це перетворює правдоподібний бал на осмислений. Ні для чого іншого вони не використовуються і ніколи не продаються.","Файли cookie та локальне сховище","Ваш вибір теми та мови зберігається в локальному сховищі браузера. Більше ми нічого на ваш пристрій не записуємо.","Реклама","Ми використовуємо Google AdSense. Google може встановлювати cookie і застосовувати їх для показу релевантної реклами. Див. %s Google.","Аналітика","Ми використовуємо Google Analytics, щоб бачити, які сторінки відвідують. Google збирає це на власних умовах, включно з приблизним місцем розташування та типом пристрою.","Ваші дані","Оскільки записи тесту не містять нічого, що вас ідентифікує, ми не можемо знайти, вивантажити чи видалити запис конкретної людини — зв'язку з вами не існує. Якщо ви волієте, щоб нічого не збиралося, просто не завершуйте тест: до появи результату нічого не надсилається.","Контакти"],
"vi": ["Chúng tôi thu thập gì","Khi bạn hoàn thành bài kiểm tra trí tuệ hoặc bài kiểm tra quy luật, chúng tôi ghi lại diễn biến: những quy luật câu đố nào xuất hiện, mỗi câu có trả lời đúng không, mỗi câu mất bao lâu, tổng điểm của bạn, ngôn ngữ và ngày. Chúng tôi không ghi tên, email, địa chỉ IP hay bất kỳ định danh tài khoản hoặc thiết bị nào, và không lưu bất cứ thứ gì giúp nhận ra bạn khi quay lại.","Vì sao","Bài kiểm tra này chưa có mẫu chuẩn hóa. Dữ liệu trả lời là cách duy nhất để đo mỗi câu đố thực sự khó đến đâu và phân tách tư duy mạnh với yếu tốt đến mức nào — đó chính là điều biến một điểm số trông hợp lý thành một điểm số có ý nghĩa. Dữ liệu không dùng cho việc gì khác và không bao giờ được bán.","Cookie và bộ nhớ cục bộ","Lựa chọn giao diện và ngôn ngữ của bạn được giữ trong bộ nhớ cục bộ của trình duyệt. Ngoài ra chúng tôi không ghi gì lên thiết bị của bạn.","Quảng cáo","Chúng tôi dùng Google AdSense. Google có thể đặt cookie và dùng chúng để hiển thị quảng cáo phù hợp. Xem %s của Google.","Phân tích","Chúng tôi dùng Google Analytics để biết trang nào được xem. Google thu thập điều đó theo điều khoản riêng của họ, gồm vị trí gần đúng và loại thiết bị.","Dữ liệu của bạn","Vì hồ sơ bài kiểm tra không chứa gì nhận dạng bạn, chúng tôi không thể tìm, xuất hay xóa mục của một cá nhân cụ thể — không có mối liên hệ nào dẫn về bạn. Nếu bạn muốn không thu thập gì cả, đơn giản là đừng hoàn thành bài kiểm tra: không có gì được gửi đi trước khi kết quả hiện ra.","Liên hệ"],
"zh": ["我们收集什么","当你完成智力测验或规律测验时，我们会记录作答过程：出现了哪些题目规律、每题是否答对、每题用了多久、你的总分、语言和日期。我们不记录姓名、邮箱、IP 地址或任何账号与设备标识，也不保存任何能让我们在你再次到访时认出你的东西。","为什么","本测验尚无常模样本。作答数据是唯一能测出每道题实际有多难、以及它区分强弱推理能力如何的途径，而这正是把一个看似合理的分数变成有意义分数的关键。这些数据不作其他用途，也从不出售。","Cookie 与本地存储","我们把你的主题和语言选择保存在浏览器的本地存储中。除此之外不会向你的设备写入任何内容。","广告","我们使用 Google AdSense。谷歌可能设置 Cookie 并用于展示相关广告。请参阅谷歌的%s。","分析统计","我们使用 Google Analytics 查看哪些页面被访问。谷歌按其自身条款收集这些信息，包括大致位置和设备类型。","你的数据","由于测验记录不含任何能识别你的信息，我们无法查找、导出或删除某一个人的记录——没有任何线索能追溯到你。如果你希望不被收集，只需不要做完测验：在结果出现之前不会发送任何内容。","联系方式"],
}

GOOG_LABEL = {
 "en":"privacy policy","af":"privaatheidsbeleid","ar":"سياسة الخصوصية","bg":"политика за поверителност","cs":"zásady ochrany soukromí","da":"privatlivspolitik","de":"Datenschutzerklärung","el":"πολιτική απορρήτου","es":"política de privacidad","et":"privaatsuspoliitikat","fa":"سیاست حریم خصوصی","fi":"tietosuojakäytäntö","fr":"politique de confidentialité","he":"מדיניות הפרטיות","hi":"गोपनीयता नीति","hr":"politiku privatnosti","hu":"adatvédelmi irányelveit","id":"kebijakan privasi","it":"informativa sulla privacy","ja":"プライバシーポリシー","ko":"개인정보처리방침","lt":"privatumo politiką","lv":"privātuma politiku","mk":"политика за приватност","ms":"dasar privasi","nl":"privacybeleid","no":"personvernerklæring","pl":"politykę prywatności","pt":"política de privacidade","ro":"politica de confidențialitate","ru":"политику конфиденциальности","sk":"zásady ochrany súkromia","sl":"politiko zasebnosti","sq":"politikën e privatësisë","sr":"политику приватности","sv":"integritetspolicy","sw":"sera ya faragha","th":"นโยบายความเป็นส่วนตัว","tl":"patakaran sa privacy","tr":"%sgizlilik politikasına","uk":"політику конфіденційності","vi":"chính sách quyền riêng tư","zh":"隐私政策",
}

BLOCK = re.compile(r'(<div class="instruction-card">\s*<p[^>]*>).*?(</p>\s*</div>)', re.S)

ready = T.ready_langs()
missing = [l for l in ready if l not in K]
if missing:
    print('NO TRANSLATIONS FOR:', missing); sys.exit(1)

n = 0
for lang in ready:
    v = K[lang]
    assert len(v) == 13, (lang, len(v))
    label = GOOG_LABEL[lang].replace('%s', '')
    body = ('<strong>%s:</strong> %s<br><br>\n      '
            '<strong>%s:</strong> %s<br><br>\n      '
            '<strong>%s:</strong> %s<br><br>\n      '
            '<strong>%s:</strong> %s<br><br>\n      '
            '<strong>%s:</strong> %s<br><br>\n      '
            '<strong>%s:</strong> %s<br><br>\n      '
            '<strong>%s:</strong> %s') % (
        v[0], v[1], v[2], v[3], v[4], v[5],
        v[6], v[7] % (GOOG % label),
        v[8], v[9], v[10], v[11], v[12], MAIL)

    f = 'privacy/index.html' if lang == 'en' else '%s/privacy/index.html' % lang
    if not os.path.isfile(f):
        print('  MISSING:', f); sys.exit(1)
    h = io.open(f, encoding='utf-8').read()
    if not BLOCK.search(h):
        print('  NO POLICY BLOCK:', f); sys.exit(1)
    h2 = BLOCK.sub(lambda m: m.group(1) + body + m.group(2), h, count=1)
    io.open(f, 'w', encoding='utf-8', newline='\n').write(h2)
    n += 1
print('privacy policy rewritten on %d pages' % n)
